"""Assemble this review's evidence contract; does not alter the package."""
import sys
sys.dont_write_bytecode=True
import json,os,subprocess
import audit
R=audit.ROOT
def main():
    stages=audit.read(R/'stage-analysis.json');probes=audit.read(R/'shortcut-probes.json')
    grader=audit.read(R/'grader-results.json')
    script_results=[]
    for name,expected in [('delivery-batch/accepted.json',1),('counterfactual-records.json',0)]:
        cmd=[str(audit.PY),str(R/'check_batch_shortcut.py'),'--input',str(R/name)]
        p=subprocess.run(cmd,capture_output=True,text=True,env=os.environ|{'PYTHONDONTWRITEBYTECODE':'1'},cwd=R)
        script_results.append({'command':cmd,'expected_exit':expected,'actual_exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr})
        assert p.returncode==expected
    audit.save('shortcut-regression-runs.json',script_results)
    cfrefs=['counterfactual-records.json','counterfactual-results.json','grader-input.json','grader-results.json','render/input.json','render-rest/input.json']
    variation={
      'learner_operation':'Use elementary row elimination to decide which residual rows vanish, then count pivots in REF and select that integer. Matrix dimensions alone give a bound, not the answer.',
      'fixed_features':[
        {'feature':'One five-option numeric radio field asking for number of pivot columns','justification':'All 17 assessed source questions use selection/radio, five integer choices. The task is a count rather than column identities.'},
        {'feature':'Sparse 3–5 row, 5–6 column matrices in normal sampling and one or two row replacements','justification':'Matches the assessed moderate source workload; the canonical 3x4 example has no captured radio control and is not a replay template.'},
        {'feature':'No row-swap branch or symbolic parameters','justification':'The supplied target KP cases use one/two row replacements; extending to extra cases is unnecessary for this review.'}],
      'answer_roles':[
        {'role':'Survival of a residual row after elimination','eligible_variation':'Zero versus nonzero residual at the same dimensions and with the same elimination roles','observed':'Controlled 3x5 pair changes one entry and rank 2 -> 3. All 17 templates show multiple ranks in independent control. Exact batch fixes corank one in all five records.'},
        {'role':'Number and columns of pivots','eligible_variation':'Vary pivot count within comparable elimination workload and shift pivot locations; derive answer and explanation from actual matrix','observed':'Control sample covers ranks 2–5 and shifted pivot columns. No justified rule requires rows-minus-one.'},
        {'role':'Correct numeric choice and its presentation position','eligible_variation':'Derive numeric choice from rank; labels and shuffled order must not identify it','observed':'All 155 tested native grader submissions behave correctly. UI independently orders choices by field and item IDs; numeric rows-minus-one bypass is unaffected by this ordering.'}],
      'coverage':[
        {'case':'All captured assessed source templates and banks','sample_refs':['source-replays.json','source-replay-results.json'],'result':'17 replayed, exact input/intermediate/final matrices and full banks/keys match; no excluded assessed cases.'},
        {'case':'Residual survival variation in independently chosen normal seeds','sample_refs':['samples.json','coverage.json','delivery-samples/accepted.json'],'result':'204/204 survive shared filtering, no generation exceptions, every template has at least two observed ranks.'},
        {'case':'Exact proposed five-record batch','sample_refs':['batch.json','delivery-batch/accepted.json','batch-shortcut-results.json'],'result':'All five survive delivery and all have rank equal to rows minus one: rows [4,4,3,3,5], answers [3,3,2,2,4].'},
        {'case':'Learner selection and history exclusions','sample_refs':['stage-analysis.json'],'result':'All are moderate. Any positive moderate weight selects uniformly among eligible moderate IDs; when only proposed items remain fresh, every draw retains shortcut (64/64). Explicit combined captured-bank scenario has counterexamples.'}],
      'counterfactuals':[
        {'kind':'relevant','change':'For q-130957, seed 74109 with explicit parameters, change final residual entry (row 3, column 5) from 0 to 1, holding all other entries, name and operations fixed. Only one input cell changes.','expected':'Rank and accepted numeric choice change 2 -> 3; prompt shows new entry and solution retains third pivot. Old choice becomes wrong.','observed':'Exact matrix/solution check passes; both rendered screenshots show the change; native grader accepts 2 only before and 3 only after, rejecting each of the other four choices.','status':'passed','justification':'Dependence after elimination is the target operation; source f1ae8763-ab2d-5aee-9b53-3f6da8520aee loses a row, whereas 02683bf4-c015-5b9c-845b-c5f836ec3faf retains a later pivot.','sample_refs':cfrefs},
        {'kind':'irrelevant','change':'Rename A to D, and separately rescale the first nonzero REF row by 2 with corresponding input reconstruction; hold residual survival fixed.','expected':'Rank and accepted numeric answer remain 3; labels/row values change consistently.','observed':'Both variants have exact rank 3, correct solution conclusion, no math errors, and native grader accepts only 3. Rendered name/scale variants pass the actual UI renderer.','status':'passed','justification':'Matrix labels are incidental and nonzero row scaling preserves row equivalence; elementary row operations are the source prerequisite.','sample_refs':cfrefs}],
      'shortcut_probes':probes,
      'delivery':{'stages_examined':['generator construction and rejection conditions','CLI mathematical-fingerprint deduplication','requested difficulty','shared normalization and content identities','captured inventory and within-batch deduplication','learner history exclusions and difficulty-first weighted selection rules','actual UI choice ordering'],
        'sample_refs':['stage-analysis.json','delivery-batch/delivery.json','delivery-batch/accepted.json','delivery-samples/delivery.json','delivered-content-comparison.json','packaging-results.json'],
        'result':'Captured basis 5362: controls 204 -> 204, batch 5 -> 5. Normalization rewrites identities but preserves prompts, solutions, bank values and answers. Batch-only fresh pool remains 100% solvable by row count minus one under all within-pool orderings/exclusions. Combined bank is not uniformly vulnerable.'},
      'limitations':['No finite sample proves absence of all shortcuts.','Actual active learner policy/history and new publication entity IDs are not captured. Selection scenarios explicitly use hypothetical fresh IDs and the inspected production rule; no database writes occur.','Canonical example lacks answer-field evidence and is not exposed as a source-replay template; its matrices and rank are independently confirmed, without inventing an answer control.','The demonstrated finding is finite-batch selection, not universal sampler failure. All 22 captured inventory questions were tested for that predicate; no affected stored pool-wide defect demonstrated.']}
    audit.save('pedagogical-variation.json',variation)
    audit.save('render-inspection.json',{'automated_reports':['render/rendering.json','render-rest/rendering.json'],'rendered_records':12,'all_passed':True,
      'visually_inspected':['render/question-001.png','render/question-006.png','render-rest/question-001.png','render-rest/question-004.png','render-rest/question-005.png','render-rest/question-006.png'],
      'observations':'Prompts, five radio controls, negative entries, row replacement annotations, fractional coefficients, 5x5 and 3x6 matrices and full worked solutions are visible and readable. Controlled zero/nonzero residual pair visually agrees with rank 2/3. No clipping, missing glyphs or overlap observed at the tested desktop viewport.',
      'limits':'Desktop 1280x1000 full-page captures; not a mobile viewport audit. Renderer previews a submitted correct answer, and is not a substitute for the native grader.'})
    refs=['f1ae8763-ab2d-5aee-9b53-3f6da8520aee','8a6c1395-93b3-574c-b784-2d33009b00c0','02683bf4-c015-5b9c-845b-c5f836ec3faf','tutorial d45a4eba-96ce-5bef-92b7-b8f0d4cd8b72: first convert to row echelon form','generate/principles.md §2']
    checks={
      'source_replay':{'status':'passed','evidence_paths':['source-analysis.json','source-replays.json','source-replay-results.json'],'details':'All 17 assessed moderate source cases replay with exact matrices at every stage, complete five-option banks and correct keys. Canonical example rank independently checked; it has no captured answer control and is not a replay template.'},
      'math':{'status':'passed','evidence_paths':['audit.py','math-results.json','delivered-content-comparison.json'],'details':'230 records independently checked from visible prompt/solution matrices using exact SymPy rational rank and row replacements; no failures. Five normalized delivered records also pass.'},
      'variety':{'status':'failed','evidence_paths':['coverage.json','samples.json','batch-shortcut-results.json','stage-analysis.json'],'details':'Normal control varies ranks in all 17 templates, but the exact delivered batch fixes corank one: [4,4,3,3,5] rows and [3,3,2,2,4] answers. This finite practice pool fails meaningful decision variety.'},
      'scope':{'status':'passed','evidence_paths':['source-analysis.json','coverage.json','math-results.json','pedagogical-variation.json'],'details':'Sampled tasks remain numeric pivot counts after one/two elementary row replacements with comparable sparse matrix sizes. Rank-2 variants use the same zero-residual reasoning. No new operators or response requirements observed.'},
      'grading':{'status':'passed','evidence_paths':['grader-input.json','grader-results.json'],'details':'Production native grade_field: 31 correct choices accepted and 124 distractors rejected across 17 source replays, exact raw batch, controlled pairs and normalized delivered batch. All fields are radio; free-entry equivalence is inapplicable.'},
      'rendering':{'status':'passed','evidence_paths':['render/rendering.json','render-rest/rendering.json','render-inspection.json','render/question-001.png','render/question-006.png','render-rest/question-001.png','render-rest/question-005.png','render-rest/question-006.png'],'details':'Actual unmodified learning UI rendered 12 records, including entire raw batch, controlled pairs and source cases with fractional coefficients and six columns. Automated checks and representative screenshot inspection pass. Shared delivery preserves their visible batch content.'},
      'packaging':{'status':'passed','evidence_paths':['packaging-results.json','package-hashes-before.json','package-hashes-after.json','external-output.json'],'details':'Exact installed Python 3.13.5 and SymPy 1.14.0 match nested manifest dependencies. Relocation, deterministic CLI replay, explicit parameter replay, external output and valid/invalid boundaries pass. Package files unchanged.'},
      'decision_variation':{'status':'failed','evidence_paths':['pedagogical-variation.json','shortcut-regression-runs.json','batch-shortcut-results.json','stage-analysis.json','affected-inventory.json','inventory-assessment.json'],'details':'Relevant/irrelevant controlled pairs pass, but selecting the numeric row count minus one succeeds on all 5 delivered records and all conditional row-count groups. Control success is only 81/204. Current captured stored pool is 5/22 (non-source subset 1/5), so finding is batch-specific.'}}
    source=audit.read(R/'source-analysis.json')
    result={'verdict':'revise','summary':'Revise the five-question batch: “count matrix rows and subtract one” answers all five surviving records without elimination. The sampler control, mathematics, native grading, rendering and packaging pass their tested checks; no generator-wide construction defect demonstrated.',
       'source_analysis':{k:source[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']},'checks':checks,
       'findings':[{'kind':'decision_shortcut','description':'The exact proposed finite practice pool is entirely corank one. Row-count-minus-one predicts every answer across 3-, 4-, and 5-row matrices, after all shared delivery filters. The source skill requires deciding dependence after elimination; source cases include full row rank and different deficits. This is a demonstrated batch-selection defect, not a universal generator defect.',
         'source_refs':refs,
         'reproduction':f'{audit.PY} {R}/check_batch_shortcut.py --input {R}/delivery-batch/accepted.json exits 1. Raw seeds 315106964..315106968, templates q-35394,q-73633,q-130957,q-130959,q-130964, produce row/rank pairs (4,3),(4,3),(3,2),(3,2),(5,4). First raw question 55fca203-3fb5-53e2-a6ba-d348030d6b89 normalizes to 78641dac-e06b-5931-a04b-b1bf5b32e8e0. The full five-record failing fixture is retained in batch.json and delivery-batch/accepted.json; explicit parameters are present. Counterfactual-records.json is a passing control for the strict test.',
         'requested_change':'Revise batch assembly/acceptance to prevent a whole delivered pool from fixing the same incidental row-count-to-answer relationship. Use existing supported same-shape instances with different residual survival/rank outcomes, then rerun this strict post-delivery regression and conditional cue checks. Preserve valid sampler families and source replay; no engine repair or generator restriction is justified by this finding. Do not mark individual stored corank-one questions defective solely for satisfying this relation.'}]}
    audit.save('review.json',result)
    commands={'python':str(audit.PY),'commands':[
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' audit.py',
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' '+str(audit.REPO/'generate/pipeline/check_delivery.py')+' --input samples.json --source ../source/source.json --inventory ../source/inventory.json --difficulty moderate --output delivery-samples --asset-root ../workspace --math-root /media/jake/SSD/EDB/math',
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' '+str(audit.REPO/'generate/pipeline/check_delivery.py')+' --input batch.json --source ../source/source.json --inventory ../source/inventory.json --difficulty moderate --output delivery-batch --asset-root ../workspace --math-root /media/jake/SSD/EDB/math',
      str(audit.REPO/'generate/runs/current/check-engine')+' grader-input.json grader-results.json',
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' '+str(audit.REPO/'generate/pipeline/render_preview.py')+' --input render-input.json --output render --asset-root ../workspace --math-root /media/jake/SSD/EDB/math',
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' '+str(audit.REPO/'generate/pipeline/render_preview.py')+' --input render-rest-input.json --output render-rest --asset-root ../workspace --math-root /media/jake/SSD/EDB/math --limit 6',
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' analyze_variation.py',
      'PYTHONDONTWRITEBYTECODE=1 '+str(audit.PY)+' finalize_review.py'],
      'notes':'All paths are relative to this evidence directory unless absolute. audit.py creates original inputs; grader-input.json was extended to include five actual shared-normalized delivered records. Render default limit is six; rest input contains remaining six records. Reproduction scripts are database-free.'}
    audit.save('commands.json',commands)
    (R/'session-state.md').write_text('Completed review; verdict revise in review.json. Demonstrated sole finding: exact batch seeds 315106964..315106968 has rank=rows-1 in 5/5 after delivery. Controls 81/204, captured inventory 5/22 and generated subset 1/5. affected-inventory.json empty with reason in inventory-assessment.json. Exact math: 230 raw/replay/control records plus 5 normalized; native grader 31 accepted/124 rejected. Actual UI 12 records passed, representative screenshots inspected. Relocation/dependencies/boundaries pass. Package file hashes unchanged. Strict batch regression exits 1 on actual batch and 0 on controlled records; code and full records retained. No package/database/publication writes. Pedagogical variation contract saved.\n')
    print(json.dumps({'verdict':result['verdict'],'failed_checks':[k for k,v in checks.items() if v['status']=='failed'],'findings':len(result['findings'])}))

if __name__=='__main__':main()
